<template><div class="page"><div class="page-header"><h2>账单管理</h2></div><el-card shadow="never"><el-table :data="items" v-loading="loading" stripe size="small" highlight-current-row @row-click="open"><el-table-column prop="bill_id" label="账单编号" width="120"/><el-table-column prop="custcd" label="客户" width="100"/><el-table-column label="结算类型" width="80"><template #default="{row}">{{ row.billing_type||'-' }}</template></el-table-column><el-table-column prop="bill_period" label="账单周期" width="100"/><el-table-column label="账单金额" width="110" align="right"><template #default="{row}">¥{{ Number(row.total_amount||0).toLocaleString() }}</template></el-table-column><el-table-column label="已付金额" width="110" align="right"><template #default="{row}">¥{{ Number(row.paid_amount||0).toLocaleString() }}</template></el-table-column><el-table-column label="状态" width="80"><template #default="{row}"><el-tag :type="billStatusTag(row.status)" size="small">{{ row.status||'PENDING' }}</el-tag></template></el-table-column><el-table-column prop="bill_date" label="账单日期" width="100"/><el-table-column prop="due_date" label="到期日" width="100"/></el-table><AppPagination v-model:current-page="page" v-model:page-size="perPage" :total="total" style="margin-top:12px;justify-content:flex-end"/></el-card><el-dialog :title="'账单 — '+(detail?.bill_id||'')" v-model="drawer" width="550px"><template v-if="detail"><el-descriptions :column="2" border size="small"><el-descriptions-item label="账单编号">{{ detail.bill_id }}</el-descriptions-item><el-descriptions-item label="客户">{{ detail.custcd||'-' }}</el-descriptions-item><el-descriptions-item label="结算类型">{{ detail.billing_type||'-' }}</el-descriptions-item><el-descriptions-item label="账单周期">{{ detail.bill_period||'-' }}</el-descriptions-item><el-descriptions-item label="账单金额">¥{{ Number(detail.total_amount||0).toLocaleString() }}</el-descriptions-item><el-descriptions-item label="税额">¥{{ Number(detail.tax_amount||0).toLocaleString() }}</el-descriptions-item><el-descriptions-item label="已付金额">¥{{ Number(detail.paid_amount||0).toLocaleString() }}</el-descriptions-item><el-descriptions-item label="状态"><el-tag :type="billStatusTag(detail.status)" size="small">{{ detail.status||'PENDING' }}</el-tag></el-descriptions-item><el-descriptions-item label="账单日期">{{ detail.bill_date||'-' }}</el-descriptions-item><el-descriptions-item label="到期日">{{ detail.due_date||'-' }}</el-descriptions-item><el-descriptions-item label="关联合同">{{ detail.htbh||'-' }}</el-descriptions-item><el-descriptions-item label="批次号">{{ detail.batch_id||'-' }}</el-descriptions-item><el-descriptions-item label="备注" :span="2">{{ detail.remark||'-' }}</el-descriptions-item></el-descriptions></template></el-dialog></div></template>
<script setup lang="ts">import AppPagination from '@/components/common/AppPagination.vue';import {useListPage} from '@/composables/useListPage';import {useDetailDrawer} from '@/composables/useDetailDrawer';import {fetchBills} from '@/api/billing';import type {BillingRecord} from '@/api/billing'
const{items,loading,page,perPage,total}=useListPage<BillingRecord>(fetchBills);const{drawer,detail,open}=useDetailDrawer<BillingRecord>()
function billStatusTag(s:string){const m:Record<string,string>={PENDING:'info',SENT:'',PARTIAL:'warning',PAID:'success',OVERDUE:'danger',CANCELLED:'info'};return m[s]||'info'}</script>
